// Parse RSS XML and extract latest articles
const xml2js = require('xml2js');
const parser = new xml2js.Parser();

const xmlData = $input.first().json.body;
let items = [];

parser.parseString(xmlData, (err, result) => {
  if (!err && result.rss && result.rss.channel && result.rss.channel[0].item) {
    items = result.rss.channel[0].item.slice(0, 2).map(item => ({
      title: item.title[0],
      link: item.link[0],
      description: item.description[0] || '',
      pubDate: item.pubDate ? item.pubDate[0] : new Date().toISOString()
    }));
  }
});

return items.map(item => ({ json: item }));

