// Transform Ollama response to blog post format
const ollamaResponse = JSON.parse($input.first().json.body);
const originalData = $('Parse RSS & Select 2 Latest').first().json;

let content = '';
let title = '';
let excerpt = '';
let tags = [];
let seoKeywords = '';

try {
  // Try to parse JSON from response
  const responseText = ollamaResponse.choices[0].message.content;

  // Extract JSON from response (handle markdown code blocks)
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    title = parsed.title || originalData.title;
    excerpt = parsed.excerpt || originalData.description.substring(0, 150) + '...';
    content = parsed.content || responseText;
    tags = parsed.tags || ['NASA', 'space news', 'space exploration'];
    seoKeywords = parsed.seoKeywords || 'NASA news, space news, space exploration';
  } else {
    // Fallback if JSON parsing fails
    title = originalData.title;
    excerpt = originalData.description.substring(0, 150) + '...';
    content = responseText;
    tags = ['NASA', 'space news'];
    seoKeywords = 'NASA news, space news';
  }
} catch (e) {
  // Fallback on error
  title = originalData.title;
  excerpt = originalData.description.substring(0, 150) + '...';
  content = ollamaResponse.choices[0]?.message?.content || originalData.description;
  tags = ['NASA', 'space news'];
  seoKeywords = 'NASA news, space news';
}

// Generate slug from title
const slug = title
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .substring(0, 60);

// Get today's date
const today = new Date().toISOString().split('T')[0];

return {
  json: {
    slug: slug,
    title: title,
    excerpt: excerpt,
    content: content,
    category: 'nasa-news',
    date: today,
    tags: tags,
    seoKeywords: seoKeywords
  }
};
